-- m175: بازنویسی زبانی سادهٔ چهار فرم اختلال یادگیری (بستهٔ کاربردی — متن برای خانواده و معلم)
-- تغییر: فقط متن گویه‌ها + لنگرهای پاسخ + مثال (hint) + متن معلم (teacherLabel/teacherHint) + توضیح فرم + توصیهٔ باندها
-- ثابت: کلیدها، تعداد/ترتیب گویه‌ها، نقش ملاکی، نمره‌دهی ۰–۲، زیرمقیاس‌ها و آستانه‌های باند — موتور استنتاج بدون تغییر
UPDATE case_event_types SET
  fields = '[{"key": "rA1", "label": "وقتی بلند می‌خواند، کند است، زیاد زحمت می‌کشد و اشتباه می‌خواند.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً هر کلمه را با مکث و سختی می‌خواند و خسته می‌شود.", "teacherLabel": "وقتی در کلاس بلند می‌خواند، کند است، زیاد زحمت می‌کشد و اشتباه می‌خواند."}, {"key": "rA2", "label": "موقع خواندن، کلمه را حدس می‌زند یا حرف‌ها را جابه‌جا می‌خواند.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً «برف» را «برق» می‌خواند یا فقط با نگاه به شکل کلمه جواب می‌دهد.", "teacherLabel": "موقع خواندن در کلاس، کلمه را حدس می‌زند یا حرف‌ها را جابه‌جا می‌خواند."}, {"key": "rA3", "label": "صداهای داخل کلمه را خوب تشخیص نمی‌دهد.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً نمی‌تواند بگوید «مداد» با چه صدایی شروع می‌شود، یا کلمه‌ای را به صداهای کوچک تقسیم کند.", "teacherLabel": "صداهای داخل کلمه را در کارهای خواندن کلاس خوب تشخیص نمی‌دهد."}, {"key": "rA4", "label": "با اینکه مدتی تمرین کرده، هنوز بعضی حرف‌ها را با صدایشان قاطی می‌کند.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً «ب» و «پ»، یا «س» و «ش».", "teacherLabel": "با اینکه مدتی تمرین کرده، هنوز در کلاس بعضی حرف‌ها را با صدایشان قاطی می‌کند."}, {"key": "rA5", "label": "کلمهٔ تازه یا ساختگی را نمی‌تواند حرف‌به‌حرف بخواند.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً کلمهٔ بی‌معنی مثل «تُمبا».", "teacherLabel": "کلمهٔ تازه یا ساختگی را هنگام خواندن در کلاس نمی‌تواند حرف‌به‌حرف بخواند."}, {"key": "rA6", "label": "در املا خیلی اشتباه می‌کند، حتی در کلمه‌هایی که بارها دیده.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً کلمه‌هایی مثل «مدرسه» یا «دوست».", "teacherLabel": "در املای کلاس خیلی اشتباه می‌کند، حتی در کلمه‌هایی که بارها دیده."}, {"key": "rB1", "label": "مشکل خواندن روی درس‌ها، حال یا اعتمادبه‌نفس او اثر گذاشته است.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "critb", "hint": "مثلاً از درس بدش آمده، می‌گوید «من نمی‌توانم»، یا نمره‌اش افت کرده."}, {"key": "rB2", "label": "برای جبران مشکل خواندن، راه دیگری پیدا کرده و زود خسته می‌شود.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "critb", "hint": "مثلاً به توضیح شفاهی گوش می‌دهد یا از روی عکس‌ها جواب را حدس می‌زند.", "teacherHint": "مثلاً از دوستش می‌خواهد بخواند، یا به‌جای خواندن متن به تصویر نگاه می‌کند."}, {"key": "rC1", "label": "این مشکل از سال‌های اول یاد گرفتن خواندن شروع شده و همیشه با او بوده.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "critc", "hint": "مثلاً از اول و دوم دبستان."}, {"key": "rD1", "label": "بینایی و شنوایی او سالم است (یا با عینک و سمعک مشکلی ندارد)، مدرسه را مرتب رفته و آموزش درست دیده؛ با این حال مشکل با تمرین معمول حل نشده.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "critd", "hint": "اگر دلیل دیگری مثل کم‌بینایی، کم‌شنوایی یا غیبت طولانی هست، گزینهٔ ۰ را بزنید و توضیح بدهید."}]',
  description = 'سلام. این فرم ده جمله دارد دربارهٔ اینکه فرزندتان در خواندن چطور عمل می‌کند. جواب درست یا غلط وجود ندارد. فقط همان چیزی را علامت بزنید که خودتان در این چند ماه دیده‌اید. اگر دربارهٔ یک جمله مطمئن نیستید، نزدیک‌ترین گزینه را انتخاب کنید و در جلسه با درمانگر حرف بزنید. حدود ۳ دقیقه وقت می‌برد. این فرم تشخیص نمی‌دهد؛ فقط به درمانگر کمک می‌کند تصویر دقیق‌تری از کودک شما داشته باشد.
اگر این فرم به معلم ارسال شده است: لطفاً هر جمله را بر اساس آنچه خودتان در کلاس دیده‌اید پاسخ بدهید، نه بر اساس حدس یا شنیده‌ها. اگر چیزی را ندیده‌اید، گزینهٔ «دیده نمی‌شود» را بزنید. دید شما از رفتار واقعی کودک در کلاس برای پروندهٔ او بسیار ارزشمند است.',
  bands = '[{"max": 10, "label": "در محدودهٔ عادی", "color": "ok", "advice": "پاسخ‌های شما نشان می‌دهد در این بخش نگرانی مهمی دیده نمی‌شود. اگر باز هم دلواپس بودید، در جلسهٔ بعد با درمانگر درباره‌اش حرف بزنید."}, {"max": 13, "label": "مرزی — نیاز به بررسی", "color": "warn", "advice": "بعضی نشانه‌ها دیده می‌شود که بهتر است بیشتر بررسی شود. این به معنی وجود اختلال نیست. درمانگر با کمک آزمون‌های دقیق‌تر و نظر معلم تصویر کامل‌تری می‌سازد."}, {"max": 9999, "label": "قابل توجه — نیاز به بررسی تخصصی", "color": "danger", "advice": "پاسخ‌های شما نشان می‌دهد این بخش نیاز به بررسی تخصصی دارد. این فرم تشخیص نیست. گام بعدی ارزیابی دقیق‌تر با درمانگر است. با کمک درست، بیشتر کودکان پیشرفت چشمگیری می‌کنند."}]'
WHERE key = 'ce-sld-read-v1' AND deleted_at IS NULL;
