UPDATE case_event_types SET
  fields = '[{"key": "cA1", "label": "«حس عدد» ضعیفی دارد؛ مقایسهٔ مقدارها برایش سخت است.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً نمی‌داند ۷ بیشتر است یا ۴."}, {"key": "cA2", "label": "برای جمع‌های ساده هنوز انگشت می‌شمارد و با گذشت زمان سریع‌تر نشده است.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita"}, {"key": "cA3", "label": "جمع و ضرب‌های پایه را با وجود تمرین زیاد از بر نشده است.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً جدول ضرب هر بار از اول فراموش می‌شود."}, {"key": "cA4", "label": "در محاسبهٔ چندمرحله‌ای راه را گم می‌کند یا یک مرحله را جا می‌اندازد.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita"}, {"key": "cA5", "label": "در مسئلهٔ کلامی، پیدا کردن راه‌حل از خود محاسبه برایش سخت‌تر است.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً نمی‌داند باید جمع کند یا کم کند."}, {"key": "cA6", "label": "مفهوم مقدار را در عمل نمی‌فهمد.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "crita", "hint": "مثلاً «نصف» و «دو برابر» را درست تشخیص نمی‌دهد."}, {"key": "cB1", "label": "مشکل ریاضی روی درس‌ها یا حال او اثر گذاشته است.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "critb"}, {"key": "cB2", "label": "با وسیلهٔ ملموس مثل مهره یا خط عدد بهتر جواب می‌دهد، ولی با عدد و نماد گیج می‌شود.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "critb"}, {"key": "cC1", "label": "مشکل از ابتدای یاد گرفتن ریاضی بوده است.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "critc"}, {"key": "cD1", "label": "آموزش کافی دیده و ضعف بیشتر مخصوص ریاضی است، نه همهٔ درس‌ها.", "type": "scale", "scaleMax": 2, "scaleLabels": ["دیده نمی‌شود", "گاهی و کم", "واضح و بارها"], "required": true, "subscaleId": "critd"}]',
  description = 'سلام. این فرم ده جمله دارد دربارهٔ اینکه فرزندتان در حساب چطور عمل می‌کند. جواب درست یا غلط وجود ندارد. فقط همان چیزی را علامت بزنید که خودتان در این چند ماه دیده‌اید. اگر دربارهٔ یک جمله مطمئن نیستید، نزدیک‌ترین گزینه را انتخاب کنید و در جلسه با درمانگر حرف بزنید. حدود ۳ دقیقه وقت می‌برد. این فرم تشخیص نمی‌دهد؛ فقط به درمانگر کمک می‌کند تصویر دقیق‌تری از کودک شما داشته باشد.
